        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IActivatorGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.VirtualMachineAdapter is IFormLinkContainerGetter VirtualMachineAdapterlinkCont)
            {
                foreach (var item in VirtualMachineAdapterlinkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AnimationSound, out var AnimationSoundInfo))
            {
                yield return AnimationSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DefaultLayer, out var DefaultLayerInfo))
            {
                yield return DefaultLayerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SnapTemplate, out var SnapTemplateInfo))
            {
                yield return SnapTemplateInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.Properties is {} PropertiesItem)
            {
                foreach (var item in PropertiesItem.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.NativeTerminal, out var NativeTerminalInfo))
            {
                yield return NativeTerminalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ForcedLocRefType, out var ForcedLocRefTypeInfo))
            {
                yield return ForcedLocRefTypeInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LoopingSound, out var LoopingSoundInfo))
            {
                yield return LoopingSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ActivationSound, out var ActivationSoundInfo))
            {
                yield return ActivationSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.WaterType, out var WaterTypeInfo))
            {
                yield return WaterTypeInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            if (FormLinkInformation.TryFactory(obj.InteractionKeyword, out var InteractionKeywordInfo))
            {
                yield return InteractionKeywordInfo;
            }
            if (obj.RadioReceiver is {} RadioReceiverItems)
            {
                foreach (var item in RadioReceiverItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.GlobalCooldownTimer, out var GlobalCooldownTimerInfo))
            {
                yield return GlobalCooldownTimerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.CNDC, out var CNDCInfo))
            {
                yield return CNDCInfo;
            }
            foreach (var item in obj.DestructibleObjectFactions.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.HGLB, out var HGLBInfo))
            {
                yield return HGLBInfo;
            }
            yield break;
        }
        
